        _e("kv_go_generics", "Go Generics (1.18+)", "go", "// Generic function\nfunc Map[T any, U any](s []T, f func(T) U) []U {\n    result := make([]U, len(s))\n    for i, v := range s {\n        result[i] = f(v)\n    }\n    return result\n}\n\n// Constrained generic\ntype Number interface {\n    int | int64 | float64\n}\nfunc Sum[T Number](nums []T) T {\n    var total T\n    for _, n := range nums {\n        total += n\n    }\n    return total\n}\n\n// Generic struct\ntype Stack[T any] struct {\n    items []T\n}\nfunc (s *Stack[T]) Push(item T) { s.items = append(s.items, item) }\nfunc (s *Stack[T]) Pop() (T, bool) {\n    if len(s.items) == 0 {\n        var zero T\n        return zero, false\n    }\n    item := s.items[len(s.items)-1]\n    s.items = s.items[:len(s.items)-1]\n    return item, true\n}", ["go","generics","type-parameters","constraints"]),

        # ═══ JAVA ═══
        _e("kv_java_streams", "Java Streams API", "java", "import java.util.*;\nimport java.util.stream.*;\n\nList<String> names = List.of(\"Alice\",\"Bob\",\"Charlie\",\"Diana\");\n\n// Filter + Map + Collect\nList<String> result = names.stream()\n    .filter(n -> n.length() > 3)\n    .map(String::toUpperCase)\n    .sorted()\n    .collect(Collectors.toList());\n\n// Reduce\nint sum = IntStream.range(1, 101).sum(); // 5050\nOptional<String> longest = names.stream()\n    .reduce((a, b) -> a.length() > b.length() ? a : b);\n\n// GroupBy\nMap<Integer, List<String>> byLength = names.stream()\n    .collect(Collectors.groupingBy(String::length));\n\n// Parallel streams\nlong count = list.parallelStream()\n    .filter(item -> item.isValid())\n    .count();\n\n// Optional\nOptional<User> user = findUser(id);\nString name = user.map(User::getName).orElse(\"Unknown\");\nuser.ifPresent(u -> sendEmail(u));", ["java","streams","optional","functional","lambda"]),
        _e("kv_java_concurrency", "Java Concurrency", "java", "// Thread creation\nThread t = new Thread(() -> System.out.println(\"Running\"));\nt.start();\n\n// ExecutorService\nExecutorService executor = Executors.newFixedThreadPool(4);\nFuture<String> future = executor.submit(() -> {\n    Thread.sleep(1000);\n    return \"Result\";\n});\nString result = future.get(); // blocks\n\n// CompletableFuture\nCompletableFuture.supplyAsync(() -> fetchData())\n    .thenApply(data -> process(data))\n    .thenAccept(result -> display(result))\n    .exceptionally(ex -> { log(ex); return null; });\n\n// Virtual Threads (Java 21)\ntry (var executor = Executors.newVirtualThreadPerTaskExecutor()) {\n    for (int i = 0; i < 10000; i++) {\n        executor.submit(() -> handleRequest());\n    }\n}\n\n// synchronized\nsynchronized(lock) {\n    sharedResource.update();\n}\n\n// ConcurrentHashMap\nConcurrentHashMap<String, Integer> map = new ConcurrentHashMap<>();\nmap.compute(\"key\", (k, v) -> v == null ? 1 : v + 1);", ["java","concurrency","threads","future","virtual-threads"]),

        # ═══ C++ ═══
        _e("kv_cpp_smart_ptr", "C++ Smart Pointers", "cpp", "#include <memory>\n\n// unique_ptr — exclusive ownership\nauto p1 = std::make_unique<Player>(\"Hero\");\n// auto p2 = p1;  // ERROR: can't copy\nauto p2 = std::move(p1);  // Transfer ownership\n\n// shared_ptr — shared ownership\nauto p3 = std::make_shared<Player>(\"Ally\");\nauto p4 = p3;  // ref count = 2\nstd::cout << p3.use_count();  // 2\n\n// weak_ptr — non-owning observer\nstd::weak_ptr<Player> wp = p3;\nif (auto sp = wp.lock()) {\n    sp->doSomething();\n}\n\n// Custom deleter\nauto filePtr = std::unique_ptr<FILE, decltype(&fclose)>(\n    fopen(\"data.txt\", \"r\"), fclose\n);\n\n// RAII pattern\nclass DatabaseConnection {\n    Connection* conn;\npublic:\n    DatabaseConnection(const std::string& url) : conn(connect(url)) {}\n    ~DatabaseConnection() { disconnect(conn); }\n    // Delete copy, allow move\n    DatabaseConnection(const DatabaseConnection&) = delete;\n    DatabaseConnection(DatabaseConnection&& other) noexcept : conn(other.conn) { other.conn = nullptr; }\n};", ["cpp","smart-pointer","raii","unique-ptr","shared-ptr"]),
        _e("kv_cpp_stl", "C++ STL Containers", "cpp", "// Vector\nstd::vector<int> v = {1, 2, 3};\nv.push_back(4);\nv.emplace_back(5);  // Construct in-place\nstd::sort(v.begin(), v.end());\nauto it = std::find(v.begin(), v.end(), 3);\n\n// Map\nstd::map<std::string, int> m;\nm[\"alice\"] = 95;\nm.insert({\"bob\", 87});\nif (m.count(\"alice\")) { ... }\nfor (auto& [key, val] : m) { ... }\n\n// unordered_map (hash map) — O(1) average\nstd::unordered_map<std::string, int> um;\n\n// Set\nstd::set<int> s = {3, 1, 4, 1, 5};  // {1, 3, 4, 5}\n\n// Stack & Queue\nstd::stack<int> stk;\nstk.push(1); stk.top(); stk.pop();\nstd::queue<int> q;\nq.push(1); q.front(); q.pop();\nstd::priority_queue<int> pq;  // max-heap\n\n// Algorithms\nstd::sort(v.begin(), v.end());\nstd::reverse(v.begin(), v.end());\nstd::accumulate(v.begin(), v.end(), 0);\nstd::transform(v.begin(), v.end(), v.begin(), [](int x){ return x*2; });", ["cpp","stl","vector","map","set","algorithm"]),

