        # ═══ SQL ADVANCED ═══
        _e("kv_sql_window", "SQL Window Functions", "sql", "-- ROW_NUMBER / RANK / DENSE_RANK\nSELECT name, salary, department,\n  ROW_NUMBER() OVER (ORDER BY salary DESC) as row_num,\n  RANK() OVER (ORDER BY salary DESC) as rank,\n  DENSE_RANK() OVER (ORDER BY salary DESC) as dense_rank,\n  NTILE(4) OVER (ORDER BY salary DESC) as quartile\nFROM employees;\n\n-- Partition\nSELECT name, department, salary,\n  AVG(salary) OVER (PARTITION BY department) as dept_avg,\n  salary - AVG(salary) OVER (PARTITION BY department) as diff_from_avg\nFROM employees;\n\n-- Running totals\nSELECT date, amount,\n  SUM(amount) OVER (ORDER BY date ROWS UNBOUNDED PRECEDING) as running_total,\n  AVG(amount) OVER (ORDER BY date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) as moving_avg_7d\nFROM transactions;\n\n-- LAG / LEAD\nSELECT month, revenue,\n  LAG(revenue, 1) OVER (ORDER BY month) as prev_month,\n  revenue - LAG(revenue) OVER (ORDER BY month) as growth,\n  LEAD(revenue) OVER (ORDER BY month) as next_month\nFROM monthly_sales;", ["sql","window-functions","analytics","rank","lag"]),
        _e("kv_sql_optimization", "SQL Query Optimization", "sql", "-- EXPLAIN ANALYZE\nEXPLAIN ANALYZE\nSELECT * FROM orders WHERE user_id = 123 ORDER BY created_at DESC LIMIT 10;\n\n-- Index types\nCREATE INDEX idx_user ON orders(user_id);              -- B-tree (default)\nCREATE INDEX idx_search ON articles USING gin(to_tsvector('english', content));  -- Full-text\nCREATE INDEX idx_geo ON places USING gist(location);   -- Spatial\nCREATE INDEX idx_active ON users(email) WHERE active = true;  -- Partial\nCREATE UNIQUE INDEX idx_email ON users(email);         -- Unique\n\n-- Composite index (leftmost prefix rule)\nCREATE INDEX idx_composite ON orders(user_id, created_at DESC);\n-- Works for: WHERE user_id = X, WHERE user_id = X ORDER BY created_at\n-- Does NOT help: WHERE created_at > X (without user_id)\n\n-- Query tips:\n-- Avoid SELECT * — specify columns\n-- Use EXISTS instead of IN for subqueries\n-- Avoid functions on indexed columns in WHERE\n-- Use LIMIT for pagination\n-- VACUUM ANALYZE regularly (PostgreSQL)", ["sql","optimization","index","explain","performance"]),

