        _e("kv_ruby_essentials", "Ruby Essentials", "ruby", "# Everything is an object\n5.times { |i| puts i }\n[1,2,3].map { |n| n * 2 }  # [2,4,6]\n(1..10).select(&:even?)     # [2,4,6,8,10]\n\n# Blocks, Procs, Lambdas\ndef with_logging\n  puts 'Start'\n  yield  # Execute block\n  puts 'End'\nend\nwith_logging { puts 'Working...' }\n\nmy_proc = Proc.new { |n| n * 2 }\nmy_lambda = ->(n) { n * 2 }\n\n# Symbols\n:name  # Immutable, interned string\nhash = { name: 'Alice', age: 30 }  # Symbol keys\n\n# Classes\nclass Dog\n  attr_accessor :name, :breed\n  def initialize(name, breed)\n    @name = name\n    @breed = breed\n  end\n  def to_s\n    \"#{@name} (#{@breed})\"\n  end\nend\n\n# Mixins\nmodule Greetable\n  def greet\n    \"Hello, I'm #{name}\"\n  end\nend\nclass Person\n  include Greetable\nend", ["ruby","blocks","procs","lambda","oop"]),
        _e("kv_php_modern", "Modern PHP 8.x", "php", "<?php\n// Named arguments\nfunction createUser(string $name, int $age, string $role = 'user'): array {\n    return compact('name', 'age', 'role');\n}\n$user = createUser(name: 'Alice', age: 30);\n\n// Match expression\n$result = match($status) {\n    'active' => 'User is active',\n    'inactive', 'banned' => 'User is disabled',\n    default => 'Unknown status',\n};\n\n// Enums\nenum Status: string {\n    case Active = 'active';\n    case Inactive = 'inactive';\n}\n\n// Readonly properties\nclass User {\n    public function __construct(\n        public readonly string $name,\n        public readonly string $email,\n    ) {}\n}\n\n// Fibers (lightweight concurrency)\n$fiber = new Fiber(function(): void {\n    $value = Fiber::suspend('first');\n    Fiber::suspend('second: ' . $value);\n});\n$fiber->start();    // 'first'\n$fiber->resume('x'); // 'second: x'\n\n// Null safe operator\n$city = $user?->getAddress()?->getCity();", ["php","php8","enums","named-arguments","match"]),
